// Created: 2026-08-21

// Guards the "agent-friendly 404s" recovery. The audit scored this Partial:
// "Nonexistent paths return a real HTTP 404. For full credit, include a short
// markdown body (site map links, where to look next) so agents can recover."
//
// What must hold: a 404 keeps its real status, AND every representation of it
// (Markdown, RFC 9457 JSON, HTML) names the same recovery hops, AND those hops
// point at paths this origin actually serves, a recovery link that 404s would
// turn one dead end into two.

import { existsSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";
import {
	isServedPath,
	prefersMarkdownError,
	shouldJsonError,
} from "@/lib/agent-404";
import { SITE } from "@/lib/constants";
import {
	notFoundExtensions,
	notFoundMarkdown,
	RECOVERY_LINKS,
} from "@/lib/not-found-body";
import { problemResponse } from "@/lib/problem";

describe("RECOVERY_LINKS", () => {
	it("points only at paths this origin serves", () => {
		// The whole point of the list is recovery. A hop that itself 404s makes the
		// dead end worse, so every href must satisfy isServedPath (query strings
		// stripped, /api/search?query= is the documented call shape).
		for (const link of RECOVERY_LINKS) {
			const path = link.href.split("?")[0] as string;
			expect(isServedPath(path), `recovery link not served: ${path}`).toBe(true);
		}
	});

	it("covers the three surfaces the audit named: sitemap, llms.txt, docs index", () => {
		const hrefs = RECOVERY_LINKS.map((l) => l.href);
		expect(hrefs).toContain("/sitemap.xml");
		expect(hrefs).toContain("/llms.txt");
		expect(hrefs.some((h) => h.startsWith("/docs"))).toBe(true);
	});

	it("every entry has a non-empty title and description", () => {
		for (const link of RECOVERY_LINKS) {
			expect(link.title.length).toBeGreaterThan(0);
			expect(link.desc.length).toBeGreaterThan(0);
		}
	});
});

describe("notFoundMarkdown", () => {
	const body = notFoundMarkdown("/nope", SITE.domain);

	it("is Markdown with a heading and the offending path", () => {
		expect(body.startsWith("# 404")).toBe(true);
		expect(body).toContain("/nope");
	});

	it("renders every recovery link as a Markdown link", () => {
		for (const link of RECOVERY_LINKS) {
			expect(body).toContain(`[${link.title}](${link.href})`);
		}
	});

	it("states that this origin never answers an unknown path with 200", () => {
		// The failure mode the audit warns about is a 200 app shell making every
		// path look real. Saying so in the body lets an agent trust the 404.
		expect(body).toMatch(/never answers an unknown path with `200`/);
	});

	it("stays short, a recovering agent needs the next hop, not an essay", () => {
		expect(body.split("\n").length).toBeLessThan(40);
	});
});

describe("notFoundExtensions (RFC 9457 §3.2)", () => {
	const ext = notFoundExtensions(SITE.domain);

	it("carries absolute recovery links", () => {
		expect(ext.links).toHaveLength(RECOVERY_LINKS.length);
		for (const l of ext.links) {
			expect(l.href.startsWith(SITE.domain)).toBe(true);
		}
	});

	it("carries a Markdown rendering so a JSON-only client needs no second call", () => {
		expect(ext.markdown).toContain("[llms.txt](/llms.txt)");
	});
});

describe("problemResponse with extensions", () => {
	it("keeps the registered members and merges the extension members", async () => {
		const res = problemResponse(
			{ title: "Resource not found", status: 404, instance: "/nope" },
			{},
			notFoundExtensions(SITE.domain),
		);
		expect(res.status).toBe(404);
		expect(res.headers.get("content-type")).toContain("application/json");
		const body = (await res.json()) as Record<string, unknown>;
		expect(body.type).toBe("about:blank");
		expect(body.title).toBe("Resource not found");
		expect(body.status).toBe(404);
		expect(body.instance).toBe("/nope");
		expect(Array.isArray(body.links)).toBe(true);
		expect(typeof body.markdown).toBe("string");
	});

	it("emits no extension members when none are passed", async () => {
		const res = problemResponse({ title: "x", status: 404 });
		expect(Object.keys((await res.json()) as object).sort()).toEqual([
			"status",
			"title",
			"type",
		]);
	});
});

describe("unknown agent-data paths reach the structured 404", () => {
	it(".md is no longer swallowed by the static-asset escape hatch", () => {
		// Regression pin: the docs tell agents to append `.md` to a page URL. Before
		// this fix, /nope.md matched the "has a file extension" branch, so an agent
		// following our own instruction received the HTML not-found page, markup,
		// not content. Verified against production on 2026-08-21:
		// `curl -sI https://orchestkit.yonyon.ai/developers.md` → 404 text/html.
		expect(isServedPath("/nope.md")).toBe(false);
		expect(shouldJsonError("GET", "/nope.md", "*/*")).toBe(true);
	});

	it(".txt probes get a structured 404 too", () => {
		expect(isServedPath("/nope.txt")).toBe(false);
		expect(shouldJsonError("GET", "/nope.txt", "*/*")).toBe(true);
	});

	it("binary/static extensions still fall through to Next", () => {
		for (const p of ["/missing.png", "/missing.woff2", "/missing.js"]) {
			expect(isServedPath(p)).toBe(true);
		}
	});

	it("real .md and .txt routes are still served", () => {
		for (const p of ["/auth.md", "/pricing.md", "/api-policy.md", "/llms.txt", "/robots.txt"]) {
			expect(isServedPath(p)).toBe(true);
		}
	});
});

describe("prefersMarkdownError", () => {
	it("is true for each of the three documented markdown entry paths", () => {
		expect(prefersMarkdownError("/nope", "text/markdown")).toBe(true);
		expect(prefersMarkdownError("/nope.md", "*/*")).toBe(true);
		expect(prefersMarkdownError("/nope", "*/*", "agent")).toBe(true);
	});

	it("is false for a plain JSON or wildcard client", () => {
		expect(prefersMarkdownError("/nope", "application/json")).toBe(false);
		expect(prefersMarkdownError("/nope", "*/*")).toBe(false);
	});
});

describe("the HTML 404 page renders the same recovery links", () => {
	it("imports RECOVERY_LINKS rather than hardcoding a second list", () => {
		// Asserted on the source, not the render: the point is that there is ONE
		// list. A duplicated literal would pass a render assertion and still drift.
		const file = resolve(__dirname, "../app/not-found.tsx");
		expect(existsSync(file)).toBe(true);
		const src = require("node:fs").readFileSync(file, "utf8") as string;
		expect(src).toContain("RECOVERY_LINKS");
		expect(src).toContain("@/lib/not-found-body");
	});
});
